INSERT INTO public.gym_subscription_events(id,gym_id,member_record_id,event_type,occurred_at,occurred_on,price,plan_name) SELECT gen_random_uuid(),r.gym_id,r.id,'created',r.created_at,(r.created_at AT TIME ZONE coalesce((SELECT data->'preferences'->>'timeZone' FROM public.gym_records g WHERE g.gym_id=r.gym_id AND g.kind='gym' LIMIT 1),'UTC'))::date,coalesce((coalesce(h.definition,r.data)->>'planPrice')::numeric,0),coalesce(h.definition,r.data)->>'plan' FROM public.gym_records r LEFT JOIN LATERAL (SELECT definition FROM public.client_membership_history WHERE gym_id=r.gym_id AND member_record_id=r.id ORDER BY recorded_at LIMIT 1) h ON true WHERE r.kind='members' AND NOT EXISTS(SELECT 1 FROM public.gym_subscription_events e WHERE e.gym_id=r.gym_id AND e.member_record_id=r.id);